const tabId = 2052873244;

const sectionsAndKits = await browserjs(tabId, () => {
  const data = [];

  // Find all section headers or group headers
  // RockAuto usually has div/tr with class or text like 'Daily Driver', 'Performance', etc.
  const allElements = document.querySelectorAll('.listing-inner, .listing-category, .listing-text-row, tbody[id^="listingcontainer"]');

  // Let's get the hierarchy
  const table = document.querySelector('table.navlist') || document.querySelector('div[id^="catalog"]');

  // Let's iterate through all listingcontainers
  const containers = document.querySelectorAll('tbody[id^="listingcontainer"]');

  containers.forEach(c => {
    // Look up previous siblings or parent headers
    let section = "Unknown";
    let cur = c;
    while (cur) {
      if (cur.previousElementSibling && cur.previousElementSibling.classList && cur.previousElementSibling.classList.contains('listing-category')) {
        section = cur.previousElementSibling.innerText;
        break;
      }
      cur = cur.parentElement;
    }

    const text = c.innerText.replace(/\s+/g, ' ').trim();

    // Find info links
    const moreInfoLink = c.querySelector('a[href*="moreinfo.php"], a[id^="moreinfo"]');
    const infoUrl = moreInfoLink ? moreInfoLink.href : null;

    data.push({
      text,
      infoUrl
    });
  });

  return data;
});

console.log("Total extracted:", sectionsAndKits.length);
sectionsAndKits.forEach((k, idx) => {
  console.log(`[${idx}] ${k.text}`);
  if (k.infoUrl) console.log(`    URL: ${k.infoUrl}`);
});

