const tabId = 2052873247;
const shot = await browser.screenshot({ tabId });
console.log("Screenshot:", shot.image);

// Check if any shadow roots or iframes exist now
const tree = await browserjs(tabId, () => {
  function getElements(root) {
    let list = [];
    for (const el of root.querySelectorAll('*')) {
      list.push({ tag: el.tagName, id: el.id, class: el.className, rect: el.getBoundingClientRect() });
      if (el.shadowRoot) {
        list.push(...getElements(el.shadowRoot));
      }
    }
    return list;
  }
  return getElements(document);
});
console.log("Elements count:", tree.length);
console.log("Elements with size > 0:", tree.filter(e => e.rect.width > 20 && e.rect.height > 20));

