const results = await browserjs(tabId, () => {
  const items = [];
  const cards = document.querySelectorAll('div[data-component-type="s-search-result"]');
  cards.forEach(c => {
    const titleEl = c.querySelector('h2 a span') || c.querySelector('h2');
    const linkEl = c.querySelector('h2 a') || c.querySelector('a.a-link-normal');
    const priceEl = c.querySelector('.a-price .a-offscreen') || c.querySelector('.a-price');
    const ratingEl = c.querySelector('.a-icon-alt');
    const reviewsEl = c.querySelector('span[aria-label*="ratings"]') || c.querySelector('.a-size-base.s-underline-text');

    if (titleEl && linkEl) {
      items.push({
        title: titleEl.innerText?.trim(),
        price: priceEl ? priceEl.innerText?.trim() : "N/A",
        rating: ratingEl ? ratingEl.innerText?.trim() : "N/A",
        reviews: reviewsEl ? reviewsEl.innerText?.trim() : "N/A",
        href: linkEl.href
      });
    }
  });
  return items;
});

console.log(`Found ${results.length} results on Amazon:`);
results.slice(0, 8).forEach((r, i) => {
  console.log(`[${i}] ${r.title}\n    Price: ${r.price} | Rating: ${r.rating} (${r.reviews})\n    URL: ${r.href}`);
});

